window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[289]={"id":"289","numero":289,"titre":"Hernie pariétale","objectifs":[{"id":"289-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une hernie, d’une éventration, d’une éviscération","contenu":"<p><span class=\"kw-clinique\">Les</span> trois entités partagent une <span class=\"kw-def\">protrusion de viscères abdominaux</span> hors de leur loge, mais se distinguent par <strong>l’orifice emprunté</strong> et l’<strong>intégrité du péritoine</strong>.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Mécanisme</th><th>Sac péritonéal</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hernie</strong></td>\n            <td>Protrusion à travers un <span class=\"kw-def\">orifice anatomique musculo-aponévrotique naturel</span> (le sac franchit le <span class=\"kw-def\">fascia transversalis</span>)</td>\n            <td><span class=\"kw-def\">Présent et indemne</span> — viscères à l’intérieur du sac</td>\n          </tr>\n          <tr>\n            <td><strong>Éventration</strong></td>\n            <td>Protrusion à travers un <span class=\"kw-def\">orifice secondaire à une incision</span> (à distance d’une <span class=\"kw-clinique\">laparotomie</span> ++, parfois cœlioscopie ; <span class=\"kw-clinique\">exceptionnellement post-traumatique</span>)</td>\n            <td><span class=\"kw-def\">Présent et indemne</span> — sac contenant toujours <span class=\"kw-clinique\">les</span> viscères</td>\n          </tr>\n          <tr>\n            <td><strong>Éviscération</strong></td>\n            <td>Désunion aiguë de la cicatrice avec <span class=\"kw-alerte\">rupture du péritoine</span></td>\n            <td>Absent — <span class=\"kw-alerte\">viscères directement exposés à l’air libre ou sous la peau</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> Hernie = orifice <em>naturel</em> ; éventration = orifice <em>cicatriciel</em> avec péritoine intact ; éviscération = <span class=\"kw-alerte\">péritoine rompu</span>, viscères à nu (<span class=\"kw-alerte\">urgence</span> chirurgicale).</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/abdominal-hernia","label":"Radiopaedia : Abdominal hernia"},{"href":"https://radiopaedia.org/articles/inguinal-hernia","label":"Radiopaedia : Inguinal hernia"}]},{"id":"289-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les principaux éléments épidémiologiques des hernies pariétales","contenu":"<p>La hernie pariétale fait partie des <span class=\"kw-def\">pathologies les plus fréquentes en chirurgie digestive</span> : <span class=\"kw-chiffre\">&gt; 250 000 opérés chaque année</span> en France.</p>\n      <p>Répartition topographique par fréquence décroissante :</p>\n      <table >\n        <thead><tr><th>Topographie</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Hernie de l’aine</span></strong> (inguinale + crurale)</td><td>La <strong>plus fréquente</strong> ; prédominance <span class=\"kw-clinique\">masculine</span> pour l’inguinale</td></tr>\n          <tr><td><strong>Hernie ombilicale</strong></td><td>À travers l’anneau ombilical</td></tr>\n          <tr><td><strong>Hernie de la ligne blanche</strong></td><td>En sus-ombilical (ép<span class=\"kw-chiffre\">iga</span>strique)</td></tr>\n        </tbody>\n      </table>\n      <p>Au sein des hernies de l’aine : la <strong><span class=\"kw-etio\">hernie crurale</span></strong> représente <span class=\"kw-chiffre\">≈ 10 %</span>, avec une prédominance <span class=\"kw-clinique\">féminine</span> et un <span class=\"kw-alerte\">haut risque d’étranglement</span>. La <strong>hernie inguinale de l’enfant</strong> touche surtout le garçon (<span class=\"kw-chiffre\">8 garçons / 1 fille</span>).</p>","frequence":0},{"id":"289-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque des différents types d’hernies pariétales","contenu":"<p>Le dénominateur commun est l’<span class=\"kw-etio\">hyperpression intra-abdominale</span> ; chaque type ajoute ses facteurs propres.</p>\n      <table >\n        <thead><tr><th>Type</th><th><span class=\"kw-def\">Facteurs de risque</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hernie pariétale (général)</strong></td>\n            <td>Situations d’<span class=\"kw-etio\">hyperpression intra-abdominale</span> : travail de force ; <span class=\"kw-ci\">grossesse</span> ; <span class=\"kw-clinique\">toux chronique / BPCO</span> ; prostatisme ; <span class=\"kw-clinique\">constipation</span> ; dysurie ; <span class=\"kw-clinique\">ascite</span> ; PKRAD</td>\n          </tr>\n          <tr>\n            <td><strong>Éventration</strong></td>\n            <td><strong>Hyperpression :</strong> mêmes FR que la hernie<br><strong>Retard de cicatrisation :</strong> <span class=\"kw-etio\">tabac</span> ; <span class=\"kw-etio\">dénutrition</span> ; <span class=\"kw-etio\">obésité</span> ; <span class=\"kw-etio\">infection du site opératoire</span> ; <span class=\"kw-etio\">corticothérapie</span><br><strong><span class=\"kw-def\">Terrain</span> :</strong> ATCD de hernie ou d’éventration<br><strong>Facteur déclenchant :</strong> <span class=\"kw-clinique\">efforts de toux post-opératoires immédiats</span> ; <span class=\"kw-alerte\">complication intra-abdominale</span> (<span class=\"kw-clinique\">fistule</span> anastomotique, <span class=\"kw-clinique\">péritonite</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Hernie inguinale de l’enfant</strong></td>\n            <td>Sexe <span class=\"kw-clinique\">masculin</span> ; <span class=\"kw-etio\">prématurité</span> ; hernie inguinale <span class=\"kw-clinique\">controlatérale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hernie ombilicale (enfant)</strong></td>\n            <td>Origine <span class=\"kw-etio\">afro-américaine</span> ; <span class=\"kw-etio\">prématurité</span></td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"289-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l’anatomie et la physiopathologie des hernies inguinales chez l’enfant et l’adulte","contenu":"<p>Le repère fondamental est la <span class=\"kw-def\">ligne ilio-pubienne de Malgaigne</span> (EIAS → pubis), projection cutanée du <span class=\"kw-def\">ligament inguinal</span> (= arcade crurale). Elle sépare <span class=\"kw-clinique\">les</span> hernies selon la position du collet :</p>\n      <ul>\n        <li><strong>Collet au-dessus</strong> de l’arcade = hernie <span class=\"kw-clinique\">inguinale</span></li>\n        <li><strong>Collet en-dessous</strong> de l’arcade = hernie <span class=\"kw-clinique\">crurale / fémorale</span></li>\n      </ul>\n      <p>Toute la région est centrée par le <span class=\"kw-def\">trou myo-pectinéal</span>, divisé en deux par le l<span class=\"kw-chiffre\">iga</span>ment inguinal ; c’est là que siègent <span class=\"kw-clinique\">les</span> points de faiblesse.</p>\n      <p>Le <span class=\"kw-def\">canal inguinal</span> livre passage au <span class=\"kw-clinique\">cordon spermatique</span> (♂) ou au <span class=\"kw-clinique\">ligament rond</span> (♀). <span class=\"kw-def\">Tunnel oblique en haut, en dehors et en arrière</span> (de l’orifice superficiel vers l’orifice profond), il est délimité par <strong>4 parois</strong> :</p>\n      <table >\n        <thead><tr><th>Paroi</th><th>Structure</th></tr></thead>\n        <tbody>\n          <tr><td><strong>En haut</strong></td><td>Faux inguinale (réunion du transverse et de l’oblique interne)</td></tr>\n          <tr><td><strong>En bas</strong></td><td>L<span class=\"kw-chiffre\">iga</span>ment inguinal (fibres du muscle oblique externe)</td></tr>\n          <tr><td><strong>En arrière</strong></td><td><span class=\"kw-def\">Fascia transversalis</span></td></tr>\n          <tr><td><strong>En avant</strong></td><td>Aponévrose du muscle oblique externe</td></tr>\n        </tbody>\n      </table>\n      <p>Il présente <strong>2 orifices</strong> : l’orifice inguinal <span class=\"kw-clinique\">superficiel</span> (palpable au doigt, coiffé par la peau du scrotum) et l’orifice inguinal <span class=\"kw-clinique\">profond</span> (non palpable, visible en cœlioscopie).</p>\n      <table >\n        <thead><tr><th>Type</th><th>Point de faiblesse</th><th>Rapport aux vaisseaux ép<span class=\"kw-chiffre\">iga</span>striques</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Inguinale oblique externe</strong> (indirecte)</td>\n            <td>Orifice inguinal profond</td>\n            <td>En <strong>DEDANS</strong> des vaisseaux ép<span class=\"kw-chiffre\">iga</span>striques (battements perçus en dedans)</td>\n            <td>Le plus souvent <span class=\"kw-etio\">congénitale</span> : persistance / reperméabilisation du <span class=\"kw-def\">canal péritonéo-vaginal</span> ; parfois <span class=\"kw-etio\">acquise</span></td>\n          </tr>\n          <tr>\n            <td><strong>Inguinale oblique interne</strong> (directe)</td>\n            <td>Fosse inguinale moyenne</td>\n            <td>En <strong>DEHORS</strong> des vaisseaux ép<span class=\"kw-chiffre\">iga</span>striques (battements perçus en dehors)</td>\n            <td><span class=\"kw-etio\">Toujours acquise</span> (faiblesse musculo-aponévrotique)</td>\n          </tr>\n          <tr>\n            <td><strong>Crurale / fémorale</strong></td>\n            <td>Canal fémoral</td>\n            <td>En <strong>DEDANS</strong> de la veine fémorale et des vaisseaux iliaques externes</td>\n            <td>Orifice fibreux inextensible → <span class=\"kw-alerte\">haut risque d’étranglement</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Manœuvre de <span class=\"kw-ttt\">réduction</span>.</strong> La hernie <span class=\"kw-clinique\">indirecte</span> se réduit en suivant le cordon — doigt coiffé du scrotum remontant obliquement <em>en haut et en dehors</em> vers l’anneau inguinal profond ; la hernie <span class=\"kw-clinique\">directe</span> se réduit selon un trajet <em>direct antéro-postérieur</em>.</p>\n      <p>Chez l’<strong>enfant</strong>, la hernie inguinale est une <span class=\"kw-def\">pathologie congénitale</span> liée à la <span class=\"kw-etio\">persistance complète du canal péritonéo-vaginal</span> : chez le garçon (<span class=\"kw-chiffre\">90 %</span>) elle suit le cordon spermatique vers le <span class=\"kw-clinique\">scrotum</span> ; chez la fille elle suit le canal de Nück et peut contenir l’ovaire.</p>\n      <div class=\"callout callout-warn\"><strong>Piège anatomique.</strong> Indirecte = en <em>dedans</em> des vaisseaux ép<span class=\"kw-chiffre\">iga</span>striques (souvent <span class=\"kw-etio\">congénitale</span>) ; directe = en <em>dehors</em> (toujours <span class=\"kw-etio\">acquise</span>). À ne pas inverser.</div>","frequence":2},{"id":"289-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les tableaux cliniques typiques","contenu":"<p>Le diagnostic est <span class=\"kw-def\">clinique</span>. La hernie est souvent <span class=\"kw-clinique\">asymptomatique</span> ou responsable d’une simple gêne-douleur, majorée par la <span class=\"kw-clinique\">toux</span>, l’<span class=\"kw-clinique\">effort</span> et la <span class=\"kw-clinique\">station debout prolongée</span>. L’examen se fait <strong>debout et couché</strong>, avec et sans effort de <span class=\"kw-clinique\">poussée</span>, en vérifiant <strong>tous <span class=\"kw-clinique\">les</span> orifices herniaires</strong>, y compris le côté controlatéral.</p>\n      <p>Trois tableaux jalonnent la gravité croissante :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hernie non compliquée</strong></td>\n            <td><span class=\"kw-clinique\">Impulsive à la toux</span> ; <span class=\"kw-clinique\">non douloureuse</span> ; <span class=\"kw-clinique\">réductible</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hernie engouée</strong></td>\n            <td><span class=\"kw-clinique\">Tuméfaction</span> <span class=\"kw-clinique\">irréductible</span> ; non douloureuse ; <span class=\"kw-alerte\">risque d’évolution vers l’étranglement</span></td>\n          </tr>\n          <tr>\n            <td><strong>Étranglement herniaire</strong></td>\n            <td><span class=\"kw-alerte\">Syndrome occlusif</span> + <span class=\"kw-clinique\">tuméfaction</span> <span class=\"kw-alerte\">non réductible, non impulsive à la toux, douloureuse</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Repérage topographique :</strong> la hernie <span class=\"kw-clinique\">crurale</span> donne une <span class=\"kw-clinique\">tuméfaction</span> <em>sous</em> la ligne de Malgaigne, en dedans des vaisseaux iliaques, à la racine de la cuisse ; la hernie <span class=\"kw-clinique\">inguinale</span> siège <em>au-dessus</em> de cette ligne.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 354 — Syndrome occlusif · 269 — Douleur abdominale aiguë</em></p>","frequence":3},{"id":"289-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques évocateur d’une hernie inguinale non compliquée chez l’enfant","contenu":"<p>La présentation diffère nettement selon le sexe, car le <strong>contenu du sac</strong> n’est pas le même.</p>\n      <table >\n        <thead><tr><th></th><th>Garçon</th><th>Fille</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Contenu</strong></td>\n            <td><span class=\"kw-clinique\">Tube digestif</span></td>\n            <td>Avant <span class=\"kw-chiffre\">6 mois</span> : <span class=\"kw-clinique\">ovaire</span><br>Après <span class=\"kw-chiffre\">6–12 mois</span> : tube digestif</td>\n          </tr>\n          <tr>\n            <td><strong>Forme non compliquée</strong></td>\n            <td><span class=\"kw-clinique\">Tuméfaction</span> indolore et souple ; <span class=\"kw-clinique\">impulsive</span> (<span class=\"kw-clinique\">toux</span>, cris, Valsalva) ; <span class=\"kw-clinique\">réductible</span> avec un <strong><span class=\"kw-clinique\">gargouillement</span></strong> caractéristique en poussant en haut et en dehors</td>\n            <td><span class=\"kw-clinique\">Tuméfaction</span> <span class=\"kw-clinique\">oblongue, centimétrique, dure</span> (consistance d’une olive), indolore, <span class=\"kw-clinique\">mobile</span> (roule sous le doigt)</td>\n          </tr>\n          <tr>\n            <td><strong>À rechercher</strong></td>\n            <td>Toujours vérifier la <span class=\"kw-alerte\">présence des testicules dans la bourse</span> (ectopie testiculaire associée possible)</td>\n            <td>Si hernie <strong>bilatérale</strong> : évoquer une <span class=\"kw-alerte\">anomalie de la différenciation sexuelle</span> (bilan <span class=\"kw-etio\">génétique</span> + endocrinien)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Ne jamais réduire une hernie de l’ovaire</strong> chez la fille : risque de traumatisme ovarien.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 50 — Pathologie génito-scrotale chez le garçon et chez l'homme</em></p>","frequence":0},{"id":"289-7","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’une hernie inguinale du garçon","contenu":"<p>La photographie attendue montre une <span class=\"kw-clinique\">tuméfaction de la région inguinale</span> du garçon, pouvant descendre dans la <span class=\"kw-clinique\">bourse</span> le long du <span class=\"kw-clinique\">cordon spermatique</span>. Elle est <span class=\"kw-clinique\">indolore</span>, <span class=\"kw-clinique\">souple</span>, <span class=\"kw-clinique\">impulsive aux cris / à la toux</span> et <span class=\"kw-clinique\">réductible</span> en poussant en haut et en dehors, avec un <strong><span class=\"kw-clinique\">gargouillement</span></strong> caractéristique.</p>\n      <div class=\"callout callout-warn\"><strong>À compléter (image).</strong> La photographie clinique n’est pas encore intégrée à la fiche. Kevin l’ajoutera depuis ses sources (Collège de <span class=\"kw-ttt\">chirurgie</span> pédiatrique / pedia-univ) via un B-FIX image. La sémiologie ci-dessus reste valable pour décrire ce que l’image illustre.</div>","frequence":0},{"id":"289-8","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes cliniques évocateurs d’une hernie étranglée chez l’enfant et l’adulte","contenu":"<p>L’étranglement est une <span class=\"kw-alerte\">urgence chirurgicale</span> exposant à la <span class=\"kw-alerte\">nécrose digestive</span>. Il est plus fréquent sur une hernie <span class=\"kw-clinique\">crurale</span> à <strong>collet étroit (<span class=\"kw-chiffre\">3–4 cm</span>)</strong>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Signes d’étranglement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Adulte</strong></td>\n            <td><strong>Local :</strong> douleur brutale sur la hernie (<span class=\"kw-clinique\">inconstante</span> → justifie la palpation systématique des orifices) ; <span class=\"kw-clinique\">tuméfaction</span> <span class=\"kw-alerte\">non réductible, non impulsive à la toux, douloureuse</span><br><strong>Occlusion par strangulation :</strong> <span class=\"kw-clinique\">arrêt des gaz et des matières</span> ; <span class=\"kw-clinique\">nausées</span>/vomissements ; météorisme</td>\n          </tr>\n          <tr>\n            <td><strong>Enfant — engouement</strong></td>\n            <td><span class=\"kw-clinique\">Tuméfaction</span> <span class=\"kw-alerte\">DURE, IRRÉDUCTIBLE, SENSIBLE</span> → <span class=\"kw-ttt\">réduction</span> par taxie en <span class=\"kw-alerte\">urgence</span> puis <span class=\"kw-ttt\">chirurgie</span> <span class=\"kw-chiffre\">24 h</span> après</td>\n          </tr>\n          <tr>\n            <td><strong>Enfant — étranglement</strong></td>\n            <td>Tableau d’<span class=\"kw-alerte\">occlusion</span> ; bourse souvent <span class=\"kw-clinique\">inflammatoire et bleutée</span> → <span class=\"kw-ttt\">chirurgie</span> en <span class=\"kw-alerte\">urgence</span>. Chez la fille, l’ovaire étranglé est <span class=\"kw-clinique\">immobile, induré, augmenté de taille et douloureux</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une <span class=\"kw-clinique\">tuméfaction</span> herniaire <em>douloureuse, irréductible et non impulsive</em> + syndrome occlusif = étranglement jusqu’à preuve du contraire → bloc.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 354 — Syndrome occlusif · 269 — Douleur abdominale aiguë</em></p>","frequence":1},{"id":"289-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d’imagerie devant une hernie pariétale","contenu":"<p>Le diagnostic de hernie pariétale est <span class=\"kw-def\">purement clinique</span> : <span class=\"kw-def\">aucun examen d’imagerie n’est nécessaire</span> dans la grande majorité des cas, <span class=\"kw-clinique\">y compris en cas d’étranglement</span> (hormis le bilan demandé par l’anesthésiste avant le bloc).</p>\n      <p>L’imagerie n’a qu’une place ciblée :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">TDM</span> : souvent demandée par le chirurgien dans l’<span class=\"kw-clinique\">éventration</span> pour <span class=\"kw-imagerie\">évaluer la taille du collet</span> avant réparation</li>\n        <li>En cas de <span class=\"kw-clinique\">doute diagnostique</span> ou de <span class=\"kw-clinique\">tuméfaction atypique</span> : <span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">TDM</span> pour confirmer la hernie et préciser son contenu</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Devant une hernie typique, demander une imagerie en <span class=\"kw-ci\">première intention</span> est une erreur : le diagnostic est <span class=\"kw-def\">clinique</span>.</div>","frequence":0},{"id":"289-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge des différents types de hernies pariétales","contenu":"<p>Le traitement est <span class=\"kw-def\">chirurgical</span> ; ses modalités dépendent du type de hernie et de l’existence d’une complication.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Principes de prise en charge</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Hernie de l’aine</span> non compliquée</strong></td>\n            <td><strong>Indications :</strong> hernie inguinale symptomatique ; hernie <span class=\"kw-alerte\">crurale même asymptomatique</span> (risque d’étranglement) ; enfant &gt;<span class=\"kw-chiffre\"> 6 mois</span> ; demande du patient<br><strong>Modalités :</strong> <span class=\"kw-ttt\">chirurgie</span> en <span class=\"kw-clinique\">ambulatoire</span>, voie ouverte (inguinale, anesthésie locale/locorégionale/générale) ou laparoscopique (AG)<br><strong>Geste selon le <span class=\"kw-def\">terrain</span> :</strong> adulte → <span class=\"kw-ttt\">réduction</span> + <strong>réparation pariétale</strong> ; <span class=\"kw-clinique\">enfant</span> → <span class=\"kw-ttt\">fermeture du canal péritonéo-vaginal</span> (garçon, en épargnant le cordon spermatique) ou du <span class=\"kw-alerte\">canal de Nück + suspension du ligament rond</span> (fille), <span class=\"kw-ci\">sans réparation pariétale</span> (pathologie <span class=\"kw-etio\">congénitale</span>)<br><strong>Réparation (adulte) :</strong> suture musculo-aponévrotique directe <em>ou</em> <span class=\"kw-ttt\">prothèse non résorbable</span> (moindre récidive)<br><strong>Suites :</strong> éviter <span class=\"kw-clinique\">les</span> efforts ≈<span class=\"kw-chiffre\"> 1 mois</span> ; arrêt de travail <span class=\"kw-chiffre\">15–42 jours</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hernie étranglée</strong> (<span class=\"kw-alerte\">urgence</span>)</td>\n            <td><strong>Initial :</strong> <span class=\"kw-ttt\">SNG</span> ; correction hydro-électrolytique ; <span class=\"kw-ttt\">antalgiques</span>, antispasmodiques, antiémétiques ; une <span class=\"kw-clinique\">réduction prudente (taxie)</span> peut éviter le bloc en <span class=\"kw-alerte\">urgence</span> et permettre une <span class=\"kw-ttt\">chirurgie</span> programmée <em>à froid</em><br><strong>Chirurgie :</strong> section du collet → <span class=\"kw-alerte\">vérification de la vitalité</span> du contenu : réintégration si rassurant, <span class=\"kw-ttt\">résection-anastomose</span> si <span class=\"kw-clinique\">nécrose</span><br><strong>Piège :</strong> <span class=\"kw-ci\">pas de prothèse si nécrose digestive</span> (risque d’infection du matériel) → raphie musculaire</td>\n          </tr>\n          <tr>\n            <td><strong>Éventration</strong></td>\n            <td>Asymptomatique à <strong>collet large</strong> : abstention possible<br>Sinon : réintégration des viscères + fermeture de l’orifice + <span class=\"kw-ttt\">renfort par prothèse non résorbable</span> (récidive ≈<span class=\"kw-chiffre\"> 50 %</span> en son absence). Si étranglée : PEC identique à la hernie étranglée<br><strong>Risques évolutifs si non opérée :</strong> étranglement (surtout si collet étroit) ; majoration inéluctable du volume → <span class=\"kw-alerte\">ulcère trophique</span>, <span class=\"kw-alerte\">complications respiratoires avec respiration paradoxale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hernie ombilicale (enfant)</strong></td>\n            <td>Fermeture spontanée habituelle vers <span class=\"kw-chiffre\">2–3 ans</span> ; <span class=\"kw-ttt\">chirurgie</span> seulement à partir de <span class=\"kw-chiffre\">4–5 ans</span> (raisons cosmétiques). Risque d’étranglement très faible</td>\n          </tr>\n          <tr>\n            <td><strong>Hernie de la ligne blanche</strong></td>\n            <td>Contenu graisseux (non dangereux) ; <span class=\"kw-ttt\">chirurgie</span> portée sur la <span class=\"kw-clinique\">symptomatologie douloureuse</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Complications de la cure de hernie</strong> (rares) :</p>\n      <table >\n        <thead><tr><th>Timing</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Per-opératoires</strong></td>\n            <td>Hémorragie ; <span class=\"kw-alerte\">section du canal déférent</span> ; <span class=\"kw-clinique\">lésion</span> d’un <span class=\"kw-clinique\">nerf inguinal ou crural</span> ; plaie du contenu herniaire</td>\n          </tr>\n          <tr>\n            <td><strong>Post-opératoires</strong></td>\n            <td>Hématome ; <span class=\"kw-alerte\">infection</span></td>\n          </tr>\n          <tr>\n            <td><strong>Tardives</strong></td>\n            <td><span class=\"kw-clinique\">Douleurs chroniques résiduelles</span> ; <span class=\"kw-chiffre\">récidive &lt; 5 %</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 354 — Syndrome occlusif · 269 — Douleur abdominale aiguë</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Étranglement</strong></p><p><span class=\"kw-ttt\">bloc</span> sans délai (hormis <span class=\"kw-bio\">bilan anesthésique</span>)</p><ul><li><span class=\"kw-alerte\">urgence chirurgicale</span> immédiate</li><li>risque de <span class=\"kw-alerte\">nécrose digestive</span></li></ul><p><strong>Engouement</strong></p><p><span class=\"kw-ttt\">réduction par taxie</span> possible puis <span class=\"kw-ttt\">chirurgie programmée</span> à <strong><span class=\"kw-chiffre\">24 h</span></strong></p><ul><li>semi-urgent</li></ul><p><strong>Non compliquée</strong></p><ul><li><span class=\"kw-ttt\">chirurgie programmée à froid</span> en ambulatoire</li><li>pas de délai impératif sauf hernie <span class=\"kw-clinique\">crurale</span> (risque élevé d'<span class=\"kw-alerte\">étranglement</span> → opérer dès le diagnostic)</li></ul><p><strong>1er geste en <span class=\"kw-alerte\">urgence</span></strong></p><ul><li><span class=\"kw-ttt\">SNG</span></li><li><span class=\"kw-ttt\">correction hydro-électrolytique</span></li><li><span class=\"kw-ttt\">antalgiques</span> / <span class=\"kw-ttt\">antispasmodiques</span> / <span class=\"kw-ttt\">antiémétiques</span></li></ul>","hospit":"<p><strong>Ambulatoire :</strong> hernie non compliquée — <span class=\"kw-ttt\">voie ouverte</span> (<span class=\"kw-ttt\">AL</span> / <span class=\"kw-ttt\">ALR</span> / <span class=\"kw-ttt\">AG</span>) ou <span class=\"kw-ttt\">laparoscopique</span> (<span class=\"kw-ttt\">AG</span>).<br><strong>Hospit programmée :</strong> exceptionnelle (<span class=\"kw-etio\">terrain fragile</span>, <span class=\"kw-etio\">comorbidités lourdes</span>).<br><strong>Hospit en <span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-alerte\">étranglement</span> → <span class=\"kw-ttt\">bloc immédiat</span> ; <span class=\"kw-alerte\">éventration étranglée</span> → idem.<br><strong>Enfant :</strong> consultation <span class=\"kw-ttt\">chirurgie</span> pédiatrique ; engouement = <span class=\"kw-ttt\">taxie</span> en urgence puis chirurgie à <span class=\"kw-chiffre\">24 h</span> ; <span class=\"kw-alerte\">étranglement</span> = <span class=\"kw-ttt\">bloc en urgence</span>.<br><strong>Spécificités :</strong> <span class=\"kw-def\">hernie crurale</span> = opérer même si asymptomatique (haut risque d'<span class=\"kw-alerte\">étranglement</span>) ; <span class=\"kw-def\">hernie ombilicale de l'enfant</span> = abstention jusqu'à <span class=\"kw-chiffre\">4-5 ans</span> (fermeture spontanée).</p>","redflags":"<ul><li><span class=\"kw-clinique\">Tuméfaction</span> herniaire <strong>douloureuse, irréductible, non impulsive à la <span class=\"kw-clinique\">toux</span></strong> → <span class=\"kw-alerte\">étranglement</span> jusqu'à preuve du contraire</li><li><span class=\"kw-alerte\">Syndrome occlusif</span> associé (<span class=\"kw-clinique\">arrêt des gaz et des matières</span>, <span class=\"kw-clinique\">nausées/vomissements</span>, <span class=\"kw-clinique\">météorisme</span>) → <span class=\"kw-alerte\">strangulation digestive</span></li><li>Hernie <span class=\"kw-clinique\">crurale</span> chez la femme (collet étroit <span class=\"kw-chiffre\">3-4 cm</span>) → <span class=\"kw-def\">terrain</span> à <span class=\"kw-alerte\">haut risque d'étranglement</span></li><li>Enfant — engouement : <span class=\"kw-clinique\">tuméfaction</span> <strong>DURE, IRRÉDUCTIBLE, SENSIBLE</strong> → <span class=\"kw-ttt\">taxie en urgence</span></li><li>Enfant — <span class=\"kw-alerte\">étranglement</span> : bourse <span class=\"kw-clinique\">inflammatoire et bleutée</span> + <span class=\"kw-alerte\">tableau occlusif</span> → <span class=\"kw-ttt\">bloc en urgence</span></li><li>Fille — <span class=\"kw-alerte\">ovaire étranglé</span> : <span class=\"kw-clinique\">tuméfaction</span> <span class=\"kw-clinique\">immobile, indurée, augmentée de taille, douloureuse</span> (jamais réduire un ovaire)</li><li>Fille — hernie inguinale <strong>bilatérale</strong> → évoquer une <span class=\"kw-alerte\">anomalie de la différenciation sexuelle</span> (<span class=\"kw-bio\">bilan génétique</span> + <span class=\"kw-bio\">endocrinien</span>)</li><li>Éventration ancienne volumineuse non opérée → <span class=\"kw-alerte\">ulcère trophique</span> ; <span class=\"kw-alerte\">complications respiratoires</span> avec <span class=\"kw-alerte\">respiration paradoxale</span></li><li>Suspicion de <span class=\"kw-alerte\">nécrose digestive</span> per-opératoire → <span class=\"kw-ci\">pas de prothèse</span> (risque d'infection du matériel), <span class=\"kw-ttt\">raphie musculaire</span> seule</li></ul>","principes":"<p>Traitement <span class=\"kw-def\">chirurgical</span> dans tous <span class=\"kw-clinique\">les</span> cas symptomatiques ou à risque. Modalités selon le type de hernie, le <span class=\"kw-def\">terrain</span> et la présence d'une complication.</p><p><strong>Hernie de l'aine non compliquée <span class=\"q\">(adulte)</span></strong></p><ul><li><span class=\"kw-ttt\">cure ambulatoire</span> — <span class=\"kw-ttt\">voie ouverte</span> (<span class=\"kw-ttt\">AL</span>/<span class=\"kw-ttt\">ALR</span>/<span class=\"kw-ttt\">AG</span>) ou <span class=\"kw-ttt\">laparoscopique</span> (<span class=\"kw-ttt\">AG</span>)</li><li><span class=\"kw-ttt\">réduction</span> + <span class=\"kw-ttt\">prothèse non résorbable</span> (moindre récidive) ou <span class=\"kw-ttt\">suture musculo-aponévrotique directe</span></li></ul><p><strong>Hernie inguinale de l'enfant <span class=\"q\">(&gt;<span class=\"kw-chiffre\"> 6 mois</span>)</span></strong></p><ul><li><span class=\"kw-alerte\">fermeture du canal péritonéo-vaginal</span> (garçon, en épargnant le cordon) ou du <strong><span class=\"kw-ttt\">canal de Nück</span> + <span class=\"kw-ttt\">suspension du ligament rond</span></strong> (fille)</li><li><span class=\"kw-ci\">sans réparation pariétale</span> (pathologie <span class=\"kw-etio\">congénitale</span>)</li></ul><p><strong>Hernie crurale <span class=\"q\">(même asympto)</span></strong></p><ul><li><span class=\"kw-ttt\">chirurgie systématique</span> dès le diagnostic — risque d'<span class=\"kw-alerte\">étranglement</span> élevé sur collet inextensible</li></ul><p><strong>Hernie ombilicale de l'enfant</strong></p><ul><li>abstention jusqu'à <span class=\"kw-chiffre\">4-5 ans</span> (fermeture spontanée habituelle vers <span class=\"kw-chiffre\">2-3 ans</span>)</li><li><span class=\"kw-ttt\">chirurgie</span> ensuite pour raisons cosmétiques</li></ul><p><strong>Hernie de la ligne blanche</strong></p><ul><li><span class=\"kw-ttt\">chirurgie</span> portée sur la <span class=\"kw-clinique\">symptomatologie douloureuse</span></li><li>contenu graisseux non dangereux</li></ul><p><strong>Hernie étranglée <span class=\"q\">(<span class=\"kw-alerte\">urgence</span>)</span></strong></p><ul><li><span class=\"kw-ttt\">SNG</span> + <span class=\"kw-ttt\">correction hydro-électrolytique</span> + <span class=\"kw-ttt\">antalgiques</span>/<span class=\"kw-ttt\">antispasmodiques</span>/<span class=\"kw-ttt\">antiémétiques</span></li><li><span class=\"kw-ttt\">bloc</span> → <span class=\"kw-ttt\">section du collet</span> → <span class=\"kw-alerte\">vérification de la vitalité</span> du contenu → <span class=\"kw-ttt\">réintégration</span> si rassurant, <span class=\"kw-ttt\">résection-anastomose</span> si <span class=\"kw-alerte\">nécrose</span></li><li><span class=\"kw-ci\">PAS de prothèse si nécrose digestive</span> (<span class=\"kw-ttt\">raphie musculaire</span>)</li></ul><p><strong>Éventration symptomatique ou à collet étroit</strong></p><ul><li><span class=\"kw-ttt\">réintégration des viscères</span> + <span class=\"kw-ttt\">fermeture de l'orifice</span> + <span class=\"kw-ttt\">renfort par prothèse non résorbable</span> (récidive ≈ <span class=\"kw-chiffre\">50 %</span> en son absence)</li></ul><p><strong>Éventration asymptomatique à collet large</strong></p><ul><li>abstention possible</li></ul>","suivi":"<p><strong>Post-op immédiat :</strong> éviction des efforts abdominaux pendant ≈ <strong><span class=\"kw-chiffre\">1 mois</span></strong>.<br><strong>Arrêt de travail :</strong> <span class=\"kw-chiffre\">15 à 42 jours</span> selon l'activité du patient.<br><strong>Complications per-opératoires (rares) :</strong> <span class=\"kw-alerte\">hémorragie</span> ; <span class=\"kw-alerte\">section du canal déférent</span> ; <span class=\"kw-alerte\">lésion d'un nerf inguinal ou crural</span> ; <span class=\"kw-alerte\">plaie du contenu herniaire</span>.<br><strong>Complications post-opératoires précoces :</strong> <span class=\"kw-alerte\">hématome</span> ; <span class=\"kw-alerte\">infection du site opératoire</span>.<br><strong>Complications tardives :</strong> <span class=\"kw-clinique\">douleurs chroniques résiduelles</span> ; <span class=\"kw-chiffre\">récidive &lt; 5 %</span>.<br><strong>Éventration non opérée :</strong> majoration inéluctable du volume → <span class=\"kw-alerte\">ulcère trophique</span>, <span class=\"kw-alerte\">respiration paradoxale</span> ; <span class=\"kw-def\">surveillance</span> clinique annuelle.</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes","label":"Pedia-univ — Douleurs abdominopelviennes"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Hernie pariétale identifiée — Quelle conduite à tenir ?","detail":"<h4>CAT — Hernie pariétale — Du statut clinique au geste chirurgical</h4>","branches":[{"to":"q-statut","label":"Statut clinique ?","color":"blue"}]},{"id":"q-statut","kind":"decision","label":"Présentation clinique — Douleur · réductibilité · syndrome occlusif","branches":[{"to":"t-etranglee","label":"Étranglée (douloureuse + irréductible + occlusion)","color":"red"},{"to":"t-engouee","label":"Engouée (irréductible non douloureuse)","color":"amber"},{"to":"q-type","label":"Non compliquée (impulsive, réductible, non douloureuse)","color":"green"}]},{"id":"t-etranglee","kind":"terminal","label":"Urgence chirurgicale","color":"red","detail":"<h4>Pré-opératoire</h4><ul><li><span class=\"kw-ttt\">SNG</span> en aspiration</li><li><span class=\"kw-ttt\">Correction hydro-électrolytique</span></li><li><span class=\"kw-ttt\">Antalgiques</span> · <span class=\"kw-ttt\">antispasmodiques</span> · <span class=\"kw-ttt\">antiémétiques</span> (<span class=\"kw-ttt\">métoclopramide</span>, <span class=\"kw-ttt\">ondansétron</span>)</li><li>Aucun examen d'imagerie nécessaire (hormis <span class=\"kw-bio\">bilan anesthésique</span>)</li><li>Une <span class=\"kw-ttt\">réduction prudente</span> PEUT éviter le <span class=\"kw-ttt\">bloc en urgence</span> et permettre une <span class=\"kw-ttt\">chirurgie programmée à froid</span></li></ul><h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li><span class=\"kw-ttt\">Incision</span> en regard de la <span class=\"kw-clinique\">tuméfaction</span> (inguinale, crurale ou péri-ombilicale)</li><li><span class=\"kw-ttt\">Section du collet herniaire</span></li><li><span class=\"kw-ttt\">Vérification de la vitalité du contenu</span></li><li>Si rassurant → <span class=\"kw-ttt\">réintégration du contenu</span></li><li>Si <span class=\"kw-alerte\">nécrose</span> ou haut risque de <span class=\"kw-alerte\">nécrose</span> → <span class=\"kw-ttt\">résection-anastomose intestinale</span></li></ul><h4>Réparation pariétale</h4><ul><li><span class=\"kw-ci\">PAS de prothèse</span> si <span class=\"kw-alerte\">nécrose digestive</span> (risque d'infection du matériel) → <span class=\"kw-ttt\">raphie musculaire</span></li></ul><h4>Délai</h4><ul><li>Immédiat — risque de <span class=\"kw-alerte\">nécrose digestive</span></li></ul>"},{"id":"t-engouee","kind":"terminal","label":"Taxie + chirurgie programmée à 24 h","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Réduction par taxie</span> en <span class=\"kw-alerte\">urgence</span> (douce, sous <span class=\"kw-ttt\">antalgiques</span>)</li><li><span class=\"kw-alerte\">Hospitalisation</span> pour <span class=\"kw-def\">surveillance</span></li><li><span class=\"kw-ttt\">Chirurgie programmée</span> à <span class=\"kw-chiffre\">24 h</span> sur la même <span class=\"kw-alerte\">hospitalisation</span></li></ul><h4>Vigilance</h4><ul><li>Risque d'<span class=\"kw-clinique\">évolution</span> vers l'<span class=\"kw-alerte\">étranglement</span> → <span class=\"kw-ci\">ne jamais</span> temporiser au-delà</li></ul>"},{"id":"q-type","kind":"decision","label":"Type de hernie ? — Topographie · terrain · symptomatologie","branches":[{"to":"t-inguinale-adulte","label":"Inguinale adulte symptomatique","color":"green"},{"to":"t-crurale","label":"Crurale (même asymptomatique)","color":"amber"},{"to":"t-inguinale-enfant","label":"Inguinale enfant > 6 mois","color":"green"},{"to":"t-ombilicale-enfant","label":"Ombilicale enfant < 4-5 ans","color":"green"},{"to":"t-ligne-blanche","label":"Ligne blanche douloureuse","color":"green"},{"to":"q-eventration","label":"Éventration","color":"amber"}]},{"id":"t-inguinale-adulte","kind":"terminal","label":"Cure programmée en ambulatoire","color":"green","detail":"<h4>Voie d'abord</h4><ul><li>Inguinale (<span class=\"kw-ttt\">AL</span>, <span class=\"kw-ttt\">ALR</span> ou <span class=\"kw-ttt\">AG</span>)</li><li>Ou <span class=\"kw-ttt\">laparoscopique</span> (<span class=\"kw-ttt\">AG</span>)</li></ul><h4>Geste</h4><ul><li><span class=\"kw-ttt\">Réduction</span> de la hernie</li><li><span class=\"kw-ttt\">Réparation pariétale</span> : <span class=\"kw-ttt\">suture musculo-aponévrotique directe</span> OU <span class=\"kw-ttt\">prothèse non résorbable</span></li><li><span class=\"kw-ttt\">Prothèse</span> → moindre risque de récidive</li></ul><h4>Suites</h4><ul><li>Éviction des efforts ≈ <span class=\"kw-chiffre\">1 mois</span> · arrêt de travail <span class=\"kw-chiffre\">15-42 jours</span> selon activité</li></ul>"},{"id":"t-crurale","kind":"terminal","label":"Chirurgie systématique","color":"amber","detail":"<h4>Pourquoi</h4><ul><li>Orifice fibreux inextensible · collet étroit (<span class=\"kw-chiffre\">3-4 cm</span>) · <span class=\"kw-etio\">prédominance féminine</span> · <span class=\"kw-alerte\">HAUT RISQUE D'ÉTRANGLEMENT</span></li></ul><h4>Conduite</h4><ul><li>Opérer dès le diagnostic, même si asymptomatique · <span class=\"kw-ttt\">cure</span> + <span class=\"kw-ttt\">prothèse non résorbable</span> habituellement</li></ul>"},{"id":"t-inguinale-enfant","kind":"terminal","label":"Fermeture du canal péritonéo-vaginal / de Nück","color":"green","detail":"<h4>Indication</h4><ul><li>Enfant > <span class=\"kw-chiffre\">6 mois</span> (pas de guérison spontanée d'une <span class=\"kw-def\">hernie inguinale congénitale</span>)</li></ul><h4>Garçon</h4><ul><li><span class=\"kw-ttt\">Réduction</span> + <span class=\"kw-ttt\">fermeture du canal péritonéo-vaginal</span> en épargnant le cordon spermatique · vérifier la présence des testicules (<span class=\"kw-def\">ectopie</span> possible)</li></ul><h4>Fille</h4><ul><li><span class=\"kw-ttt\">Réduction</span> + <span class=\"kw-ttt\">fermeture du canal de Nück</span> + <span class=\"kw-ttt\">suspension du ligament rond</span> · NE JAMAIS réduire une <span class=\"kw-alerte\">hernie de l'ovaire</span> en pré-op</li></ul><h4>Spécificité</h4><ul><li><span class=\"kw-ci\">PAS de réparation pariétale</span> (pathologie <span class=\"kw-etio\">congénitale</span>, paroi saine)</li></ul>"},{"id":"t-ombilicale-enfant","kind":"terminal","label":"Abstention — fermeture spontanée","color":"green","detail":"<h4><span class=\"kw-clinique\">Évolution</span> naturelle</h4><ul><li>Apparition dans <span class=\"kw-clinique\">les</span> premières semaines de vie</li><li>Augmentation de volume <span class=\"kw-clinique\">les</span> premiers mois</li><li>Stabilisation vers <span class=\"kw-chiffre\">9 mois</span></li><li>Fermeture spontanée durant la <span class=\"kw-chiffre\">2e ou 3e année</span></li></ul><h4>Risque</h4><ul><li>Risque d'<span class=\"kw-alerte\">étranglement</span> extrêmement faible</li></ul><h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li>Posée seulement à partir de <span class=\"kw-chiffre\">4-5 ans</span>, pour raisons cosmétiques</li></ul>"},{"id":"t-ligne-blanche","kind":"terminal","label":"Chirurgie sur symptomatologie","color":"green","detail":"<h4>Contenu</h4><ul><li>Toujours graisseux (graisse prépéritonéale ou épiploon) → non dangereux, pas d'organe noble</li></ul><h4>Indication</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> portée sur la <span class=\"kw-clinique\">symptomatologie douloureuse</span> uniquement · pas d'indication systématique</li></ul>"},{"id":"q-eventration","kind":"decision","label":"Éventration — collet étroit ou symptomatique ? — TDM utile pour évaluer la taille du collet","branches":[{"to":"t-eventration-op","label":"Oui (symptomatique ou collet étroit)","color":"amber"},{"to":"t-eventration-abst","label":"Non (asymptomatique + collet large)","color":"green"}]},{"id":"t-eventration-op","kind":"terminal","label":"Réparation + prothèse non résorbable","color":"amber","detail":"<h4>Geste</h4><ul><li><span class=\"kw-ttt\">Réintégration des viscères</span> dans la cavité abdominale</li><li><span class=\"kw-ttt\">Fermeture de l'orifice</span> en restaurant si possible une anatomie normale</li><li><span class=\"kw-ttt\">Renfort par prothèse non résorbable</span></li></ul><h4>Pourquoi la prothèse</h4><ul><li>Récidive ≈ <span class=\"kw-chiffre\">50 %</span> en son absence</li></ul><h4>Si étranglée</h4><ul><li>PEC identique à la <span class=\"kw-alerte\">hernie étranglée</span> — <span class=\"kw-ci\">PAS de prothèse</span> si <span class=\"kw-alerte\">nécrose digestive</span> (<span class=\"kw-ttt\">raphie</span> seule)</li></ul><h4>Imagerie pré-op</h4><ul><li><span class=\"kw-imagerie\">TDM</span> souvent demandée par le chirurgien pour évaluer la taille du collet</li></ul>"},{"id":"t-eventration-abst","kind":"terminal","label":"Abstention possible","color":"green","detail":"<h4>Indication</h4><ul><li><span class=\"kw-def\">Éventration asymptomatique</span> à collet large peut ne pas être opérée</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Risques évolutifs si non opérée : <span class=\"kw-alerte\">étranglement</span> (surtout si collet étroit)</li><li>Majoration inéluctable du volume → <span class=\"kw-alerte\">ulcère trophique</span>, <span class=\"kw-alerte\">complications respiratoires</span> avec <span class=\"kw-alerte\">respiration paradoxale</span></li><li><span class=\"kw-def\">Surveillance</span> clinique annuelle</li></ul>"}]},"cards":[{"i":"4c3ea4db1d2a","n":289,"o":"289-1","u":"Définition","t":"Connaître la définition d’une hernie, d’une éventration, d’une éviscération","q":"Quelle est la définition d'une hernie pariétale ?","a":"<p>Une hernie pariétale correspond à la protrusion de viscères abdominaux à travers un <strong>orifice musculo-aponévrotique anatomique naturel</strong>. Le <strong>sac péritonéal est présent et indemne</strong>, contenant les viscères.</p>"},{"i":"a97347c777bf","n":289,"o":"289-1","u":"Définition","t":"Connaître la définition d’une hernie, d’une éventration, d’une éviscération","q":"Quelle est la définition d'une éventration ?","a":"<p>Une éventration est une protrusion de viscères abdominaux à travers un <strong>orifice secondaire à une incision</strong> (le plus souvent post-laparotomie). Le <strong>sac péritonéal est présent et indemne</strong>, et contient les viscères.</p>"},{"i":"c4050a43e119","n":289,"o":"289-1","u":"Définition","t":"Connaître la définition d’une hernie, d’une éventration, d’une éviscération","q":"Quelle est la définition d'une éviscération ?","a":"<p>Une éviscération est une <strong>désunion aiguë de la cicatrice</strong> avec <strong>rupture du péritoine</strong>. Les viscères sont directement exposés à l'air libre ou sous la peau, car il n'y a <strong>pas de sac péritonéal</strong>. C'est une <strong>urgence chirurgicale</strong>.</p>"},{"i":"2292b436fa70","n":289,"o":"289-5","u":"Diagnostic positif","t":"Connaître les tableaux cliniques typiques","q":"Comment différencier topographiquement une hernie crurale d'une hernie inguinale à l'examen clinique ?","a":"<p>La différenciation topographique s'effectue par rapport à la <strong>ligne de Malgaigne</strong> :</p><ul><li>La <strong>hernie crurale</strong> se situe <strong>sous la ligne de Malgaigne</strong>, en dedans des vaisseaux iliaques, à la racine de la cuisse.</li><li>La <strong>hernie inguinale</strong> siège <strong>au-dessus</strong> de cette ligne.</li></ul>"},{"i":"350c1d72c46f","n":289,"o":"289-5","u":"Diagnostic positif","t":"Connaître les tableaux cliniques typiques","q":"Comment établit-on le diagnostic d'une hernie pariétale non compliquée et quelles en sont les caractéristiques sémiologiques principales ?","a":"<p>Le diagnostic de hernie pariétale est <strong>clinique</strong>. Une hernie non compliquée est caractérisée par :</p><ul><li>Une tuméfaction <strong>impulsive à la toux</strong>.</li><li>Elle est généralement <strong>non douloureuse</strong> ou responsable d'une simple gêne.</li><li>Elle est <strong>réductible</strong>.</li></ul>"},{"i":"710e3a8354e4","n":289,"o":"289-5","u":"Diagnostic positif","t":"Connaître les tableaux cliniques typiques","q":"Dans quelles positions et manœuvres doit-on examiner un patient suspect de hernie pariétale ?","a":"<p>L'examen clinique doit être réalisé :</p><ul><li>En positions <strong>debout et couchée</strong>.</li><li>Avec et sans <strong>effort de poussée</strong> (manœuvre de Valsalva).</li><li>Il est essentiel de vérifier <strong>tous les orifices herniaires</strong>, y compris le côté controlatéral.</p></ul>"},{"i":"89f2dd5230fc","n":289,"o":"289-5","u":"Diagnostic positif","t":"Connaître les tableaux cliniques typiques","q":"Quels sont les éléments sémiologiques évocateurs d'une hernie engouée ?","a":"<p>Une hernie engouée se manifeste par :</p><ul><li>Une <strong>tuméfaction irréductible</strong>.</li><li>Elle est généralement <strong>non douloureuse</strong>.</li><li>Elle présente un <strong>risque</strong> d'évolution vers l'étranglement.</li></ul>"},{"i":"e64a0aad3ea9","n":289,"o":"289-5","u":"Diagnostic positif","t":"Connaître les tableaux cliniques typiques","q":"Quels sont les signes cliniques distinctifs d'un étranglement herniaire ?","a":"<p>L'étranglement herniaire est un tableau grave caractérisé par :</p><ul><li>Un <strong>syndrome occlusif</strong> (associant des vomissements, un arrêt des matières et des gaz).</li><li>Une <strong>tuméfaction non réductible</strong>.</li><li>La tuméfaction est <strong>douloureuse</strong> à la palpation.</li><li>Elle est <strong>non impulsive à la toux</strong>.</li></ul>"},{"i":"13a71fd0be64","n":289,"o":"289-6","u":"Diagnostic positif","t":"Connaître les signes cliniques évocateur d’une hernie inguinale non compliquée chez l’enfant","q":"Quels sont les signes cliniques évocateurs d'une hernie inguinale non compliquée chez la fille, et quelle est la spécificité concernant sa réduction ?","a":"<p>Chez la fille, une hernie inguinale non compliquée se présente comme une <strong>tuméfaction oblongue, centimétrique, dure</strong> (de consistance d'une olive), <strong>indolore et mobile</strong> (roule sous le doigt).</p><p>Le contenu du sac est un <strong>ovaire</strong> avant 6 mois, puis du <strong>tube digestif</strong> après 6-12 mois.</p><p>Il ne faut <strong>jamais réduire manuellement une hernie contenant un ovaire</strong> chez la fille en raison du risque de traumatisme ovarien.</p>"},{"i":"4f70ec38d949","n":289,"o":"289-6","u":"Diagnostic positif","t":"Connaître les signes cliniques évocateur d’une hernie inguinale non compliquée chez l’enfant","q":"Quels sont les points complémentaires à vérifier lors de l'examen clinique d'une hernie inguinale chez l'enfant ?","a":"<p>Lors de l'examen clinique, il est important de :</p><ul><li>Toujours vérifier la présence des <strong>testicules dans la bourse</strong> pour dépister une éventuelle <strong>ectopie testiculaire associée</strong>.</li><li>Si la hernie est <strong>bilatérale</strong>, il faut évoquer une <strong>anomalie de la différenciation sexuelle</strong> et prévoir un bilan génétique et endocrinien.</li></ul>"},{"i":"5214a8e5aade","n":289,"o":"289-6","u":"Diagnostic positif","t":"Connaître les signes cliniques évocateur d’une hernie inguinale non compliquée chez l’enfant","q":"Quels sont les signes cliniques évocateurs d'une hernie inguinale non compliquée chez le garçon ?","a":"<p>Chez le garçon, une hernie inguinale non compliquée se manifeste par :</p><ul><li>Une <strong>tuméfaction indolore et souple</strong>.</li><li>Elle est <strong>impulsive</strong> à la toux, aux cris ou à la manœuvre de Valsalva.</li><li>Elle est <strong>réductible</strong> avec un <strong>gargouillement caractéristique</strong> en poussant vers le haut et l'extérieur.</li><li>Le contenu est généralement du <strong>tube digestif</strong>.</li></ul>"},{"i":"5c030e44e0e1","n":289,"o":"289-7","u":"Contenu multimédia","t":"Photographie d’une hernie inguinale du garçon","q":"Comment tente-t-on de réduire une hernie inguinale chez le garçon et quel signe peut-on observer ?","a":"<p>La hernie inguinale est <strong>réductible</strong> en poussant <strong>en haut et en dehors</strong>, et peut s'accompagner d'un <strong>gargouillement caractéristique</strong>.</p>"},{"i":"64f61929a0aa","n":289,"o":"289-7","u":"Contenu multimédia","t":"Photographie d’une hernie inguinale du garçon","q":"Quelle est l'apparence caractéristique d'une hernie inguinale chez le garçon à l'examen clinique ?","a":"<p>Une hernie inguinale chez le garçon se présente comme une <strong>tuméfaction de la région inguinale</strong>, pouvant descendre dans la bourse le long du cordon spermatique.</p>"},{"i":"9f39843446d9","n":289,"o":"289-7","u":"Contenu multimédia","t":"Photographie d’une hernie inguinale du garçon","q":"Quelles sont les caractéristiques palpatoires d'une hernie inguinale chez le garçon ?","a":"<p>La tuméfaction est classiquement :</p><ul><li><strong>Indolore</strong></li><li><strong>Souple</strong></li><li><strong>Impulsive aux cris ou à la toux</strong></li></ul>"},{"i":"03a14f1aeecb","n":289,"o":"289-8","u":"Identifier une urgence","t":"Connaître les signes cliniques évocateurs d’une hernie étranglée chez l’enfant et l’adulte","q":"Comment définir une hernie étranglée et quelle en est la principale complication ?","a":"<p>Une hernie étranglée est une hernie dont le contenu est <strong>incarcéré</strong> dans le sac herniaire avec une compression vasculaire, exposant à une <strong>ischémie digestive</strong> et à la <strong>nécrose digestive</strong>. C'est une <strong>urgence chirurgicale</strong> absolue.</p>"},{"i":"13c6d9e76701","n":289,"o":"289-8","u":"Identifier une urgence","t":"Connaître les signes cliniques évocateurs d’une hernie étranglée chez l’enfant et l’adulte","q":"Quelles sont les spécificités des signes cliniques d'une hernie étranglée chez l'enfant et chez la petite fille ?","a":"<p>Chez l'enfant, l'étranglement se manifeste par un <strong>tableau d'occlusion</strong>. La bourse peut être <strong>inflammatoire et bleutée</strong>, nécessitant une <strong>chirurgie en urgence</strong>.</p><p>Chez la fille, un <strong>ovaire étranglé</strong> sera <strong>immobile, induré, augmenté de taille et douloureux</strong>, et constitue également une urgence.</p>"},{"i":"37a8cea47d8a","n":289,"o":"289-8","u":"Identifier une urgence","t":"Connaître les signes cliniques évocateurs d’une hernie étranglée chez l’enfant et l’adulte","q":"Sur quel type de hernie l'étranglement est-il le plus fréquemment observé ?","a":"<p>L'étranglement est plus fréquent sur une <strong>hernie crurale</strong> en raison de son <strong>collet étroit</strong> (diamètre de 3-4 cm).</p>"},{"i":"7502a12f58cb","n":289,"o":"289-8","u":"Identifier une urgence","t":"Connaître les signes cliniques évocateurs d’une hernie étranglée chez l’enfant et l’adulte","q":"Comment doit être prise en charge une hernie étranglée chez l'adulte et quel est le signe d'alarme principal ?","a":"<p>Une tuméfaction herniaire <strong>douloureuse, irréductible et non impulsive</strong> associée à un <strong>syndrome occlusif</strong> doit être considérée comme une hernie étranglée jusqu'à preuve du contraire et impose une <strong>intervention chirurgicale en urgence</strong> (au bloc opératoire).</p>"},{"i":"a7e10e84cf25","n":289,"o":"289-8","u":"Identifier une urgence","t":"Connaître les signes cliniques évocateurs d’une hernie étranglée chez l’enfant et l’adulte","q":"Quels sont les signes cliniques généraux évocateurs d'une hernie étranglée chez l'adulte ?","a":"<p>Une hernie étranglée peut entraîner un tableau d'<strong>occlusion par strangulation</strong>, se manifestant par :</p><ul><li>Un <strong>arrêt du transit</strong> (gaz et matières).</li><li>Des <strong>nausées</strong> et/ou <strong>vomissements</strong>.</li><li>Un <strong>météorisme</strong> abdominal.</li></ul>"},{"i":"cdf5c38d0f5f","n":289,"o":"289-8","u":"Identifier une urgence","t":"Connaître les signes cliniques évocateurs d’une hernie étranglée chez l’enfant et l’adulte","q":"Quelles sont les spécificités des signes cliniques d'un engouement herniaire chez l'enfant ?","a":"<p>L'engouement herniaire chez l'enfant se caractérise par une tuméfaction herniaire :</p><ul><li><strong>DURE</strong>.</li><li><strong>IRRÉDUCTIBLE</strong>.</li><li><strong>SENSIBLE</strong>.</li></ul><p>La prise en charge initiale est une <strong>réduction par taxie en urgence</strong>, suivie d'une chirurgie dans les 24 heures.</p>"},{"i":"f073ee4c7701","n":289,"o":"289-8","u":"Identifier une urgence","t":"Connaître les signes cliniques évocateurs d’une hernie étranglée chez l’enfant et l’adulte","q":"Quels sont les signes cliniques locaux évocateurs d'une hernie étranglée chez l'adulte ?","a":"<ul><li>Une <strong>douleur</strong> brutale au niveau de la hernie, bien que cela puisse être inconstant, justifiant une palpation systématique des orifices herniaires.</li><li>Une <strong>tuméfaction</strong> herniaire <strong>non réductible</strong>.</li><li>Une tuméfaction <strong>non impulsive à la toux</strong>.</li><li>Une tuméfaction <strong>douloureuse</strong> à la palpation.</li></ul>"}]};